<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::sendSecurityHeaders($config);Security::startSession($config);if(!Security::enforceAuthenticatedSession($config)){Security::destroySession();header('Location: login.php');exit;}$message='';$error='';
try{$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if(!$user)throw new RuntimeException('Account unavailable.');if($_SERVER['REQUEST_METHOD']==='POST'){if(!Security::verifyCsrf($_POST['_csrf']??null))throw new RuntimeException('Security token expired. Refresh and try again.');$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$q=$db->prepare('SELECT password_hash FROM users WHERE user_id=:u');$q->execute(['u'=>$user['user_id']]);$hash=(string)$q->fetchColumn();if(!password_verify($current,$hash))throw new InvalidArgumentException('Current password is incorrect.');if(strlen($new)<12||strlen($new)>200||!preg_match('/[A-Z]/',$new)||!preg_match('/[a-z]/',$new)||!preg_match('/[0-9]/',$new)||!preg_match('/[^A-Za-z0-9]/',$new))throw new InvalidArgumentException('Use 12–200 characters with uppercase, lowercase, number, and symbol.');if($new!==$confirm)throw new InvalidArgumentException('New password and confirmation do not match.');if(password_verify($new,$hash))throw new InvalidArgumentException('Choose a password different from your current password.');$q=$db->prepare('UPDATE users SET password_hash=:h,password_changed_at=NOW(),updated_at=NOW() WHERE user_id=:u');$q->execute(['h'=>password_hash($new,PASSWORD_DEFAULT),'u'=>$user['user_id']]);AuditLogger::record($db,(int)$user['user_id'],'ACCOUNT_PASSWORD_CHANGED','user',(int)$user['user_id']);Security::rotateCsrfToken();$message='Password updated successfully.';}}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Account settings: '.$e->getMessage());$error='Unable to update account settings. Please try again.';}
$base=rtrim(dirname($_SERVER['SCRIPT_NAME']),'/\\');if($base==='/')$base='';function settingsUrl(string $p=''):string{global $base;return $base.'/'.ltrim($p,'/');}require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Account Settings');?><main class="section"><article class="content-panel"><h1>Account Settings</h1><p>Update your account password. Use a unique password that you do not use on other websites.</p><?php if($message):?><div class="notice info" role="status"><?= Security::e($message) ?></div><?php endif;?><?php if($error):?><div class="notice warning" role="alert"><?= Security::e($error) ?></div><?php endif;?><form method="post" action="<?= Security::e(settingsUrl('account_settings.php')) ?>"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><label>Current password<input type="password" name="current_password" autocomplete="current-password" required></label><label>New password<input type="password" name="new_password" minlength="12" maxlength="200" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="12" maxlength="200" autocomplete="new-password" required></label><p class="micro">At least 12 characters, including uppercase, lowercase, a number, and a symbol.</p><button class="action-primary" type="submit">Update password</button></form><p><a href="<?= Security::e(settingsUrl('dashboard.php')) ?>">Return to dashboard</a></p></article></main><?php pageFooter();
